// Map registry. Every map is a Tiled JSON file in assets/maps/ (generated by
// scripts/build-maps.mjs, editable in Tiled). MapManager turns one into a
// GameMap; gameplay code only uses the map id.
//
// Layers MapManager understands (see systems/MapData.js):
//   Ground / Blocked (tiles), Props, Collision, Entities, Spawns, Nodes (objects)

export const MAPS = {
    village: { id: 'village', tilemapKey: 'map.village', file: 'maps/village.json' },
    lostPath: { id: 'lostPath', tilemapKey: 'map.lostPath', file: 'maps/lost_path.json' },
};
